    /// Does this clip have a unload handler
    pub fn has_unload_handler(self) -> bool {
        self.clip_actions()
            .iter()
            .any(|handler| handler.effective_events.contains(ClipEventFlag::UNLOAD))
    }

    pub fn avm2_constructor_failed(self) -> bool {
